@@ -1,0 +1,334 @@
+(() => {
+  'use strict';
+
+  const QUESTIONS = [
+    {
+      id: 'q1',
+      text: 'Which of the following are statically typed languages?',
+      helpId: 'q1-help',
+      helpText: 'A statically typed language checks types at compile time rather than at run time. Select all that apply.',
+      options: [
+        { value: 'c',      label: 'C' },
+        { value: 'python', label: 'Python' },
+        { value: 'java',   label: 'Java' },
+        { value: 'js',     label: 'JavaScript' },
+      ],
+      correct: new Set(['c', 'java']),
+    },
+    {
+      id: 'q2',
+      text: 'Which languages were originally designed primarily for web development?',
+      options: [
+        { value: 'php',    label: 'PHP' },
+        { value: 'cpp',    label: 'C++' },
+        { value: 'js',     label: 'JavaScript' },
+        { value: 'cobol',  label: 'COBOL' },
+      ],
+      correct: new Set(['php', 'js']),
+    },
+    {
+      id: 'q3',
+      text: 'Which programming languages natively support multiple inheritance?',
+      options: [
+        { value: 'python', label: 'Python' },
+        { value: 'java',   label: 'Java' },
+        { value: 'cpp',    label: 'C++' },
+        { value: 'go',     label: 'Go' },
+      ],
+      correct: new Set(['python', 'cpp']),
+    },
+  ];
+
+  // ── DOM helpers ─────────────────────────────────────────────────────────────
+
+  const $ = (sel, ctx = document) => ctx.querySelector(sel);
+  const $$ = (sel, ctx = document) => [...ctx.querySelectorAll(sel)];
+
+  // ── Build quiz ───────────────────────────────────────────────────────────────
+
+  function buildQuiz() {
+    const form = $('#quiz-form');
+    if (!form) return;
+
+    QUESTIONS.forEach((q, idx) => {
+      const card = document.createElement('div');
+      card.className = 'form-field';
+      card.dataset.qid = q.id;
+
+      const fieldset = document.createElement('fieldset');
+      fieldset.id = `fs-${q.id}`;
+
+      const describedBy = [];
+      if (q.helpId) describedBy.push(q.helpId);
+      describedBy.push(`${q.id}-error`);
+      fieldset.setAttribute('aria-describedby', describedBy.join(' '));
+
+      // legend
+      const legend = document.createElement('legend');
+      const numSpan = document.createElement('span');
+      numSpan.className = 'question-number';
+      numSpan.textContent = `Question ${idx + 1} of ${QUESTIONS.length}`;
+      legend.appendChild(numSpan);
+      legend.appendChild(document.createTextNode(q.text));
+      fieldset.appendChild(legend);
+
+      // optional help text
+      if (q.helpText) {
+        const helpP = document.createElement('p');
+        helpP.id = q.helpId;
+        helpP.className = 'help-text';
+        // info icon
+        helpP.innerHTML = `
+          <svg class="help-icon" aria-hidden="true" focusable="false" viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg">
+            <circle cx="8" cy="8" r="7" stroke="currentColor" stroke-width="1.5"/>
+            <path d="M8 7v4" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/>
+            <circle cx="8" cy="5" r=".75" fill="currentColor"/>
+          </svg>
+          ${escapeHtml(q.helpText)}`;
+        fieldset.appendChild(helpP);
+      }
+
+      // options
+      const ul = document.createElement('ul');
+      ul.className = 'options-list';
+      q.options.forEach(opt => {
+        const li = document.createElement('li');
+        li.className = 'option-item';
+        const inputId = `${q.id}-${opt.value}`;
+        const input = document.createElement('input');
+        input.type = 'checkbox';
+        input.id = inputId;
+        input.name = q.id;
+        input.value = opt.value;
+        const label = document.createElement('label');
+        label.htmlFor = inputId;
+        label.textContent = opt.label;
+        li.appendChild(input);
+        li.appendChild(label);
+        ul.appendChild(li);
+      });
+      fieldset.appendChild(ul);
+
+      // error message (hidden initially)
+      const errorP = document.createElement('p');
+      errorP.id = `${q.id}-error`;
+      errorP.className = 'error-message';
+      errorP.setAttribute('aria-hidden', 'true');
+      errorP.innerHTML = `
+        <svg class="review-icon" aria-hidden="true" focusable="false" viewBox="0 0 16 16" fill="none">
+          <circle cx="8" cy="8" r="7" stroke="currentColor" stroke-width="1.5"/>
+          <path d="M8 5v3.5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/>
+          <circle cx="8" cy="11" r=".75" fill="currentColor"/>
+        </svg>
+        Error: Please select at least one answer before submitting.`;
+      fieldset.appendChild(errorP);
+
+      card.appendChild(fieldset);
+      form.appendChild(card);
+    });
+
+    // submit button row
+    const actionsDiv = document.createElement('div');
+    actionsDiv.className = 'form-actions';
+    actionsDiv.innerHTML = `
+      <button type="submit" class="btn-submit">
+        <svg aria-hidden="true" focusable="false" width="16" height="16" viewBox="0 0 16 16" fill="none">
+          <path d="M3 8h10M9 4l4 4-4 4" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/>
+        </svg>
+        Submit answers
+      </button>`;
+    form.appendChild(actionsDiv);
+
+    form.addEventListener('submit', handleSubmit);
+  }
+
+  // ── Submission ───────────────────────────────────────────────────────────────
+
+  function handleSubmit(e) {
+    e.preventDefault();
+    const form = e.currentTarget;
+
+    // Validate: every question needs ≥1 selection
+    let firstInvalid = null;
+    let allValid = true;
+
+    QUESTIONS.forEach(q => {
+      const card = form.querySelector(`[data-qid="${q.id}"]`);
+      const checked = $$(`input[name="${q.id}"]:checked`, form);
+      const errorEl = $(`#${q.id}-error`);
+
+      if (checked.length === 0) {
+        allValid = false;
+        card.classList.add('has-error');
+        errorEl.setAttribute('aria-hidden', 'false');
+        if (!firstInvalid) firstInvalid = $(`input[name="${q.id}"]`, form);
+      } else {
+        card.classList.remove('has-error');
+        errorEl.setAttribute('aria-hidden', 'true');
+      }
+    });
+
+    if (!allValid) {
+      setStatus('Some questions are unanswered. Please answer every question and try again.');
+      firstInvalid.focus();
+      return;
+    }
+
+    // Score
+    let score = 0;
+    const results = QUESTIONS.map(q => {
+      const selected = new Set(
+        $$(`input[name="${q.id}"]:checked`, form).map(i => i.value)
+      );
+      const isCorrect =
+        selected.size === q.correct.size &&
+        [...selected].every(v => q.correct.has(v));
+      if (isCorrect) score++;
+      return { q, selected, isCorrect };
+    });
+
+    showResults(results, score);
+    setStatus(`Quiz submitted. You scored ${score} out of ${QUESTIONS.length}.`);
+  }
+
+  // ── Results ───────────────────────────────────────────────────────────────────
+
+  function showResults(results, score) {
+    const quizSection = $('#quiz-section');
+    const resultsPanel = $('#results-panel');
+    const scoreDisplay = $('#score-display');
+    const scoreMessage = $('#score-message');
+    const answerReview = $('#answer-review');
+
+    // hide quiz, show results
+    quizSection.hidden = true;
+    resultsPanel.classList.add('visible');
+    resultsPanel.hidden = false;
+
+    // score
+    scoreDisplay.textContent = `${score} / ${QUESTIONS.length}`;
+    const pct = score / QUESTIONS.length;
+    scoreMessage.textContent =
+      pct === 1   ? '🎉 Perfect score! You really know your languages.' :
+      pct >= 0.67 ? '👍 Great work! A couple to brush up on.' :
+      pct >= 0.34 ? '📚 Not bad — keep learning!' :
+                    '🤔 Tricky stuff. Give it another go!';
+
+    // per-question review
+    answerReview.innerHTML = '';
+    results.forEach(({ q, selected, isCorrect }, idx) => {
+      const card = document.createElement('div');
+      card.className = 'review-card';
+
+      const qTitle = document.createElement('p');
+      qTitle.className = 'review-question';
+      qTitle.textContent = `Q${idx + 1}. ${q.text}`;
+      card.appendChild(qTitle);
+
+      const ul = document.createElement('ul');
+      ul.className = 'review-options';
+      ul.setAttribute('aria-label', `Answers for question ${idx + 1}`);
+
+      q.options.forEach(opt => {
+        const li = document.createElement('li');
+        li.className = 'review-option';
+        const wasSelected = selected.has(opt.value);
+        const isCorrectAnswer = q.correct.has(opt.value);
+
+        let iconHtml = '';
+        if (wasSelected && isCorrectAnswer) {
+          li.classList.add('correct-selected');
+          iconHtml = checkIcon();
+        } else if (wasSelected && !isCorrectAnswer) {
+          li.classList.add('incorrect-selected');
+          iconHtml = crossIcon();
+        } else if (!wasSelected && isCorrectAnswer) {
+          li.classList.add('missed');
+          iconHtml = missedIcon();
+        } else {
+          iconHtml = `<span class="review-icon" aria-hidden="true"></span>`;
+        }
+
+        li.innerHTML = `${iconHtml}<span>${escapeHtml(opt.label)}</span>`;
+        ul.appendChild(li);
+      });
+
+      card.appendChild(ul);
+      answerReview.appendChild(card);
+    });
+
+    // move focus to score heading
+    const scoreHeading = $('#results-heading');
+    scoreHeading.focus();
+  }
+
+  // ── Retry ─────────────────────────────────────────────────────────────────────
+
+  function handleRetry() {
+    const form = $('#quiz-form');
+    form.reset();
+
+    // Clear error states
+    QUESTIONS.forEach(q => {
+      const card = form.querySelector(`[data-qid="${q.id}"]`);
+      card.classList.remove('has-error');
+      $(`#${q.id}-error`).setAttribute('aria-hidden', 'true');
+    });
+
+    $('#quiz-section').hidden = false;
+    const resultsPanel = $('#results-panel');
+    resultsPanel.classList.remove('visible');
+    resultsPanel.hidden = true;
+
+    setStatus('Quiz reset. You can try again.');
+    $('input[type="checkbox"]', form).focus();
+  }
+
+  // ── Utilities ─────────────────────────────────────────────────────────────────
+
+  function setStatus(msg) {
+    const el = $('#status-msg');
+    el.textContent = '';
+    // Force re-announcement by briefly clearing
+    requestAnimationFrame(() => { el.textContent = msg; });
+  }
+
+  function escapeHtml(str) {
+    return str
+      .replace(/&/g, '&amp;')
+      .replace(/</g, '&lt;')
+      .replace(/>/g, '&gt;')
+      .replace(/"/g, '&quot;');
+  }
+
+  function checkIcon() {
+    return `<svg class="review-icon" aria-hidden="true" focusable="false" viewBox="0 0 16 16" fill="none">
+      <circle cx="8" cy="8" r="7" fill="#bbf7d0" stroke="#16a34a" stroke-width="1.5"/>
+      <path d="M5 8l2 2 4-4" stroke="#15803d" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
+    </svg>`;
+  }
+
+  function crossIcon() {
+    return `<svg class="review-icon" aria-hidden="true" focusable="false" viewBox="0 0 16 16" fill="none">
+      <circle cx="8" cy="8" r="7" fill="#fecaca" stroke="#dc2626" stroke-width="1.5"/>
+      <path d="M5.5 5.5l5 5M10.5 5.5l-5 5" stroke="#b91c1c" stroke-width="1.5" stroke-linecap="round"/>
+    </svg>`;
+  }
+
+  function missedIcon() {
+    return `<svg class="review-icon" aria-hidden="true" focusable="false" viewBox="0 0 16 16" fill="none">
+      <circle cx="8" cy="8" r="7" fill="#fef08a" stroke="#ca8a04" stroke-width="1.5"/>
+      <path d="M8 5v3" stroke="#854d0e" stroke-width="1.5" stroke-linecap="round"/>
+      <circle cx="8" cy="10.5" r=".75" fill="#854d0e"/>
+    </svg>`;
+  }
+
+  // ── Init ──────────────────────────────────────────────────────────────────────
+
+  document.addEventListener('DOMContentLoaded', () => {
+    buildQuiz();
+    const retryBtn = $('#retry-btn');
+    if (retryBtn) retryBtn.addEventListener('click', handleRetry);
+  });
+})();
+
')

