const { chromium } = require('playwright');
const path = require('path');
const fs = require('fs');

(async () => {
  const html = fs.readFileSync('index.html', 'utf8');
  // Inline CSS and JS so page.setContent works without a server
  const css = fs.readFileSync('style.css', 'utf8');
  const js  = fs.readFileSync('quiz.js',  'utf8');
  const inlined = html
    .replace('<link rel="stylesheet" href="style.css">', `<style>${css}</style>`)
    .replace('<script src="quiz.js"></script>', `<script>${js}</script>`);

  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.setContent(inlined, { waitUntil: 'load' });
  // Wait for quiz.js DOMContentLoaded to fire and build the form
  await page.waitForSelector('.form-field');
  await page.addScriptTag({ path: '/tmp/axe.min.js' });

  const r = await page.evaluate(async () => await window.axe.run());
  await browser.close();

  const wcag = r.violations.filter(v => !v.tags.includes('best-practice'));
  const bp   = r.violations.filter(v =>  v.tags.includes('best-practice'));

  console.log(JSON.stringify({
    wcag: wcag.map(v => ({ id: v.id, impact: v.impact, description: v.description,
      nodes: v.nodes.map(n => ({ target: n.target, html: n.html, failureSummary: n.failureSummary })) })),
    bp:   bp.map(v => ({ id: v.id,
      nodes: v.nodes.map(n => ({ target: n.target, html: n.html })) }))
  }, null, 2));

  process.exit(wcag.length ? 1 : 0);
})();
EOF
