  padding: 0;
  min-width: 0;
}

.question-number {
  font-size: .75rem;
  font-weight: 600;
  letter-spacing: .05em;
  text-transform: uppercase;
  color: var(--color-primary);
  margin-bottom: .25rem;
  display: block;
}

legend {
  font-size: 1rem;
  font-weight: 600;
