  gap: .375rem;
}

.help-icon {
  flex-shrink: 0;
  width: 1rem;
  height: 1rem;
  color: var(--color-primary);
}

/* ===== Checkbox options ===== */
.options-list {
  display: flex;
  flex-direction: column;
  gap: .5rem;
  list-style: none;
}

.option-item label {
  display: flex;
  align-items: center;
  gap: .75rem;
